"use client";

/**
 * Role-aware sidebar: every item is filtered through `can()` and its flag.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import Link from "next/link";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav, type NavItem } from "@/config/nav";
import { cn } from "@/lib/cn";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { orgPath, projectPath } from "@/lib/url";
import { orgFlagContext } from "@/hooks/flag-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { OrgSwitcher } from "./org-switcher";

export type AppSidebarProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  pathname: string;
  /** Orgs offered by the switcher; defaults to just the current one. */
  organizations?: readonly Organization[];
};

/** True when `pathname` is the item's route or lives beneath it. */
export function isActiveSegment(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function AppSidebar(props: AppSidebarProps): ReactElement | null {
  const { org, actor, flags, projects, pathname, organizations } = props;

  // The nav tree declares the permission and flag each item needs; `visibleNav`
  // applies both. Nothing here branches on `actor.role`.
  const context = orgFlagContext(org, actor);
  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
  const settings = visibleNav(SETTINGS_NAV, actor, flags);

  // The project shortcut list is its own gate: reading projects at all, and
  // the public-projects flag for the "shared" affordance.
  const mayReadProjects = can(
    actor,
    "project:read",
    organizationResource(org.id),
  );
  const publicProjectsOn =
    flags.public_projects === true || isEnabled("public_projects", context);

  function renderItem(item: NavItem): ReactElement {
    const href = orgPath(org.slug, item.segment);
    return (
      <li key={item.key}>
        <Link
          href={href}
          className={cn(
            "block rounded px-2 py-1 text-sm",
            isActiveSegment(pathname, href)
              ? "bg-neutral-200 font-medium"
              : "hover:bg-neutral-100",
          )}
        >
          {item.label}
        </Link>
        {item.children !== undefined && item.children.length > 0 ? (
          <ul className="ml-3 mt-0.5 space-y-0.5">
            {item.children.map(renderItem)}
          </ul>
        ) : null}
      </li>
    );
  }

  return (
    <nav className="app-sidebar flex w-56 shrink-0 flex-col gap-4 border-r p-3">
      <OrgSwitcher
        organizations={organizations ?? [org]}
        currentSlug={org.slug}
      />

      <ul className="space-y-0.5">{primary.map(renderItem)}</ul>

      {mayReadProjects && projects.length > 0 ? (
        <section>
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Projects
          </h2>
          <ul className="mt-1 space-y-0.5">
            {projects.map((project) => {
              const href = projectPath(org.slug, project.slug);
              return (
                <li key={project.id}>
                  <Link
                    href={href}
                    className={cn(
                      "flex items-center justify-between rounded px-2 py-1 text-sm",
                      isActiveSegment(pathname, href)
                        ? "bg-neutral-200 font-medium"
                        : "hover:bg-neutral-100",
                    )}
                  >
                    <span className="truncate">{project.name}</span>
                    {publicProjectsOn && project.visibility === "public" ? (
                      <span className="text-xs text-neutral-500">public</span>
                    ) : null}
                  </Link>
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {settings.length > 0 ? (
        <section className="mt-auto">
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Settings
          </h2>
          <ul className="mt-1 space-y-0.5">{settings.map(renderItem)}</ul>
        </section>
      ) : null}
    </nav>
  );
}

import type {
  FeatureFlagDefinition,
  FeatureFlagKey,
} from "@/types/feature-flag";

/**
 * Declarative registry of every feature flag. `isEnabled()` in
 * `src/lib/feature-flags.ts` is the only reader — UI and server code go
 * through that function, never through this table directly.
 */
export const FEATURE_FLAG_DEFINITIONS: Readonly<
  Record<FeatureFlagKey, FeatureFlagDefinition>
> = {
  kanban_board: {
    key: "kanban_board",
    label: "Kanban board",
    description: "Drag-and-drop board view for a project's issues.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  ai_issue_summary: {
    key: "ai_issue_summary",
    label: "AI issue summary",
    description: "Generates a short summary of a long issue thread.",
    strategy: { kind: "percentage", percent: 25 },
    overridable: true,
  },
  command_palette: {
    key: "command_palette",
    label: "Command palette",
    description: "Ctrl+K quick navigation and actions.",
    strategy: { kind: "on" },
    overridable: false,
  },
  activity_feed: {
    key: "activity_feed",
    label: "Activity feed",
    description: "Organization-wide audit trail view.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  public_projects: {
    key: "public_projects",
    label: "Public projects",
    description: "Share a read-only project page outside the organization.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
  webhooks: {
    key: "webhooks",
    label: "Outgoing webhooks",
    description: "Deliver domain events to an external HTTP endpoint.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: false,
  },
  csv_export: {
    key: "csv_export",
    label: "CSV export",
    description: "Export issues and the audit log as CSV.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  digest_email: {
    key: "digest_email",
    label: "Daily digest email",
    description: "Batches notifications into one daily email.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  issue_templates: {
    key: "issue_templates",
    label: "Issue templates",
    description: "Prefilled issue bodies per project.",
    strategy: { kind: "role", minRole: "admin" },
    overridable: true,
  },
  advanced_search: {
    key: "advanced_search",
    label: "Advanced search",
    description: "Field-scoped query syntax across issues and comments.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
};

export const FEATURE_FLAG_KEYS = Object.keys(
  FEATURE_FLAG_DEFINITIONS,
) as readonly FeatureFlagKey[];

export function getFlagDefinition(key: FeatureFlagKey): FeatureFlagDefinition {
  return FEATURE_FLAG_DEFINITIONS[key];
}

export function isFeatureFlagKey(value: string): value is FeatureFlagKey {
  return Object.prototype.hasOwnProperty.call(FEATURE_FLAG_DEFINITIONS, value);
}

